        AscendC::LocalTensor<half> srcLocal = ...;
        AscendC::LocalTensor<int16_t> dstLocal = ...;

        // 使用 RINT 模式
        AscendC::AscendCUtils::SetRintMode();  // 视具体平台接口而定
        AscendC::asc_half2int16(dstLocal, srcLocal, count);
    }
};
```

