constexpr int32_t VL = 256; // 伪代码示例

// 伪代码示意：按不同接口调用选取对应索引
// 例如接口 a 对应索引0，接口 b 对应索引1，接口 c 对应索引2，接口 d 对应索引3
// 实际使用中需根据具体场景选取合适的索引

// 通用模式：
// asc_int4x22int16(dst, src, index); // index 由调用次序/不同接口决定
